    "outDedupe": "Merge overlapping lines on export (for laser)",
    "outDedupeTip": "When exporting SVG, PDF or DXF, overlapping lines (edges shared by neighboring cells, doubled lines, the same curve with slightly shifted vertices, the same arc) are exported once, so the laser does not travel the same place again and again. The drawing data is not changed. For overlaps of different colors the colored line is kept. Lines with a stitch-hole route and painted shapes are exported as they are.",
    "outDedupeNote": "Removed {mm} mm of overlapping lines on export ({n} shapes tidied).",
    "outBeamFix": "Beam Studio correction (SVG)",
    "outBeamFixTip": "Beam Studio sizes each color layer about one stroke width (about 0.35 mm) too large and shrinks it to fit, so thin layers (only dotted lines or stitch holes) shrink by a few percent and drift from the cut line. When on, the cut line (pattern layer) is left untouched and only the dotted/hole layers are pre-adjusted so they shrink the same way as the cut line (layers whose smaller side is 5 mm or more). The cut size is the same as without the correction. It is on by default, because the laser SVG is normally opened in Beam Studio; turn it off for other software (your choice is remembered).",
    "outBeamFixNote": "Corrected {n} layer(s) for Beam Studio.",
