    "bifoldNote": "The bi-fold numbers are listed as (1)-(6), matching the numbers on the light-blue dimension lines of the section: (1) front cover width, (2) back cover width (blank = same as the front), (3) spine inner radius, (4) overall height, (5)(6) leather thickness. Enable rings for a planner; leave them off for a wallet. No button holes are added.",
