    "foldSideSpine": "Spine",
    "foldDesignTitle": "Bi-fold / tri-fold design",
    "foldDesignNote": "Make the section of the finished (wrapped) shape first. Enter, from the button line (the vertical line the button passes through all 3 layers), the distance to the outside of each fold, the distance to each cut end of the leather, and the inner radius of each fold, then press the button. Enter the thickness of the outer and the inner leather in the two thickness fields below (blank = 'Thickness of one leather'; 2 glued). The overall width (leftmost to rightmost) is the sum of the left and right distances; entering it keeps the left distance and adjusts the right one. Move the button with the Button left/right buttons (they rewrite the four distance fields; the overall width does not change). Sizes where folds overlap or the third layer pokes through a fold are still made, with a warning.",
