    "autoDimTitle": "All at once (whole drawing)",
    "adNote": "Adds dimension lines to the whole drawing (Guide layer, dashed lines, marks and hardware are skipped; tick \u201cOnly the selected shapes\u201d to limit it to the selection). Overall width and height are taken at the widest point of each piece (connected lines); slots and holes inside a piece get no overall size. Symmetric edges are dimensioned on one side only. Stitch spacing is shown per range that differs from the tool selected in the stitching card: one span line labelled \u201cstitch ○○ mm ×n\u201d (average spacing and count). Places that already have a dimension are left alone. Ticking or unticking a box adds or removes only that kind of automatic dimension right away (dimensions you drew by hand are kept).",
