    "patchSymmetryTip": "Resets the pattern position (left-right and up-down) to 0 and rebuilds this grid. Columns, rows, width and height stay as they are. Use it after changing sizes and moving the pattern, to return to the symmetric layout (Undo is one step).",
    "patchSymmetryDone": "Re-centered symmetrically.",
    "patchSymmetryNone": "No grid to re-center. Select a piece of the grid (or its frame lines).",
    "patchShiftNote": "Slide the whole pattern up, down, left or right a little at a time to balance how it looks. The pattern stays cut at the outline of the shape. After you draw a pattern, changing a number or pressing a button redraws it on the spot. Moving it afterwards with the keyboard arrows would push it past the shape, so adjust the position here instead.",
