    "patchRimRadius": "Outer stitch line: corner rounding radius (mm; 0 = no rounding)",
    "patchRimNote": "Works only while \"Also add seams and stitch holes\" is checked. Outer holes are nudged or left out so they never touch the shape's lines, the pattern pieces' lines or other holes.",
