    "patchRimRadiusCut": "A corner radius of {R} mm is too large for this shape, so {r} mm was used.",
    "patchRimFail": "The outer stitch line cannot be made (the shape is too small or the distance from the edge is too large). Use a smaller distance.",
    "patchRimTooClose": "The outer stitch line is too close to the edge (less than {w} mm between the diamond hole and the edge, so the leather can tear). Use a distance of {m} mm or more.",
